"""RoboPaint episode record: observed-camera calibration and brush trajectories.
All robot state is obtained through the standard client. No reset is used.
"""
import sys, json, time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); RUNS=Path('/app/runs')
QUAT=np.array([0.,1.,0.,0.])
PAPER_Z=.0202
SCALE=.227185/1024

class Painter:
 def __init__(self):
  self.r=Robot()
  self.obs=self.r.get_obs(cameras=['practice_cam'],video='none')
  self.pose=self.obs.group('tcp_pose',now=True)
  self.target=self.pose.copy()
 def send(self, xyz, note='', cameras=['practice_cam'], video='none'):
  xyz=np.asarray(xyz,dtype=float)
  if xyz.shape[1]==3:xyz=np.column_stack([xyz,np.tile(QUAT,(len(xyz),1))])
  for start in range(0,len(xyz),180):
   a=xyz[start:start+180]
   before=self.r.status()
   idx=before['calls']+1
   np.save(OUT/f'actions_{idx:04d}.npy',a)
   t=time.time()
   try:res=self.r.submit('ee_pose',a,dt=.05,cameras=cameras,video=video,video_fps=20,note=note)
   except Exception:
    after=self.r.wait_ready(); print('RECOVERY',before,after,flush=True)
    raise
   res.save(str(RUNS/f'{idx:04d}'))
   for c,im in res.last.items():Image.fromarray(im).save(OUT/f'latest_{c}.png')
   self.pose=res.group('tcp_pose',now=True);self.target=a[-1].copy()
   print(json.dumps({'call':idx,'n':len(a),'wall':round(time.time()-t,2),'tip':self.pose[:3].tolist(),'plan':res.meta.get('plan'),'left':res.meta.get('time_left_s')}),flush=True)
   if res.stopped or res.done:raise RuntimeError('Stopped: '+str(res.meta))
 def move(self, xyz, speed=.06, hold=.3, **kw):
  xyz=np.array(xyz)
  n=max(1,int(np.ceil(np.linalg.norm(xyz-self.target[:3])/speed/.05)))
  arr=np.linspace(self.target[:3],xyz,n+1)[1:]
  if hold:arr=np.vstack([arr,np.tile(xyz,(round(hold/.05),1))])
  self.send(arr,**kw)
 def observe(self,name='obs',cams=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=False):
  o=self.r.get_obs(cameras=cams,depth=depth);o.save(str(RUNS/name))
  for c,im in o.last.items():Image.fromarray(im).save(OUT/f'{name}_{c}.png')
  print('OBS',o.meta['proprio']['now'][7:14],flush=True)
  return o
 def park(self):
  self.move([self.pose[0],self.pose[1],.10])
  self.move([-.08,-.185,.10])
 def dip(self):
  self.move([self.pose[0],self.pose[1],.08])
  self.move([-.10,.18,.08])
  self.move([-.10,.18,.023],speed=.025,hold=.5)
  self.move([-.10,.18,.08],speed=.04)

def main():
 p=Painter()
 mode=sys.argv[1]
 if mode=='park':
  p.park();p.observe('clear',depth=True)
 elif mode=='dip':
  p.dip();p.park();p.observe('dipped',depth=True)
 elif mode=='json':
  cmds=json.load(open(sys.argv[2]))
  for c in cmds:
   getattr(p,c.pop('op'))(**c)
 else:raise ValueError(mode)
if __name__=='__main__':main()
