import numpy as np
from scipy import ndimage as ndi

def contours(mask):
 """Oriented edge contours of a binary pixel region, in (u,v)."""
 m=np.pad(mask,1)
 ys,xs=np.where(m[1:-1,1:-1]&~m[:-2,1:-1]);edges=[((x-.5,y-.5),(x+.5,y-.5)) for y,x in zip(ys,xs)]
 ys,xs=np.where(m[1:-1,1:-1]&~m[1:-1,2:]);edges += [((x+.5,y-.5),(x+.5,y+.5)) for y,x in zip(ys,xs)]
 ys,xs=np.where(m[1:-1,1:-1]&~m[2:,1:-1]);edges += [((x+.5,y+.5),(x-.5,y+.5)) for y,x in zip(ys,xs)]
 ys,xs=np.where(m[1:-1,1:-1]&~m[1:-1,:-2]);edges += [((x-.5,y+.5),(x-.5,y-.5)) for y,x in zip(ys,xs)]
 graph={}
 for a,b in edges:graph.setdefault(a,[]).append(b)
 paths=[]
 while graph:
  a=next(iter(graph));start=a;path=[a]
  while True:
   nxt=graph[a].pop()
   if not graph[a]:del graph[a]
   path.append(nxt);a=nxt
   if a==start:break
   if a not in graph:break
  if len(path)>5:paths.append(np.array(path))
 return paths

def smooth_loop(loop,sigma=1.3):
 loop=loop[:-1]
 out=ndi.gaussian_filter1d(loop,sigma,axis=0,mode='wrap')
 return np.vstack([out,out[0]])

